use super::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress};
fn debit(bank:&mut RetainedCloneGrant,work:u64,p:RetainedCloneProgress){assert!(work<=bank.maximum_items as u64);assert!(p.fits(*bank));bank.maximum_items-=work as usize;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;}
#[test]
fn actual_alias_admission_preserves_original_and_reports_atomic_work_without_heap_or_copy(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();let s=&row["stock"];
 let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};
 let turn=CancelToken::admit_root(RetainedCloneGrant{maximum_items:1,..bank});let(root,p)=turn.result.unwrap().unwrap();debit(&mut bank,turn.work,p);let pointer=Arc::as_ptr(&root.0);
 for grant in [RetainedCloneGrant{maximum_items:0,..bank},RetainedCloneGrant{maximum_depth:0,..bank}]{let(turn,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||root.admit_alias(grant));assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(Arc::strong_count(&root.0),1);assert_eq!(Arc::as_ptr(&root.0),pointer);}
 let(turn,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||root.admit_alias(RetainedCloneGrant{maximum_items:1,..bank}));assert_eq!(turn.work,1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let(alias,p)=turn.result.unwrap().unwrap();assert_eq!(serde_json::to_value(p).unwrap(),row["receipt"]);debit(&mut bank,turn.work,p);assert!(root.is_same_node(&alias));assert_eq!(Arc::strong_count(&root.0),2);
 let(oracle,_registration)=futures_util::future::AbortHandle::new_pair();let before=alias.is_cancelled_now();assert_eq!(before,oracle.is_aborted());root.cancel_now();oracle.abort();let after=alias.is_cancelled_now();assert_eq!(after,oracle.is_aborted());assert_eq!(serde_json::json!([before,after]),row["cancellation"]);
 let mut retained=crate::CancelTokenRetirement::from_token(alias);let(turn,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||retained.return_alias_step(&root,RetainedCloneGrant{maximum_items:1,..bank}));assert_eq!(turn.work,1);debit(&mut bank,turn.work,turn.result.unwrap().progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(retained.terminal_is_empty());assert_eq!(Arc::strong_count(&root.0),1);assert_eq!(Arc::as_ptr(&root.0),pointer);let cached=retained.close_step(Default::default());assert_eq!(cached.work,0);drop(retained);
 let mut retained=crate::CancelTokenRetirement::from_token(root);for _ in 0..s["maximumTurns"].as_u64().unwrap(){if retained.terminal_is_empty(){break;}let(turn,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||retained.close_step(RetainedCloneGrant{maximum_items:1,..bank}));assert_eq!(turn.work,1);let p=turn.result.unwrap().progress();assert_eq!(p.copied_bytes,0);assert_eq!((p.retained_capacity_bytes,p.released_bytes),(heap.requested_bytes,heap.released_bytes));debit(&mut bank,turn.work,p);}assert!(retained.terminal_is_empty());
}
